// Applica le modifiche: la chat non si chiude piu' cliccando fuori.
// Uso: salva nella cartella RADICE del progetto e lancia:  node applica-modifiche.js
import { writeFileSync, mkdirSync, readFileSync } from 'fs'
import { dirname } from 'path'

const files = {
  "src/components/ChatNuovoViaggio.jsx": '',
  "src/pages/Home.jsx": '',
}

for (const [percorso, b64] of Object.entries(files)) {
  mkdirSync(dirname(percorso), { recursive: true })
  writeFileSync(percorso, Buffer.from(b64, 'base64'))
  console.log('scritto:', percorso)
}

const chat = readFileSync('src/components/ChatNuovoViaggio.jsx', 'utf8')
console.log(chat.includes('chiediChiusura')
  ? '\nVERIFICA OK — conferma di chiusura presente.'
  : '\nATTENZIONE — stai eseguendo una versione vecchia dello script.')
console.log('Ora: git add . && git commit -m "chat: niente chiusura al clic fuori" && git push')